import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef
{
	public static void main (String[] args) throws java.lang.Exception
	{
		// your code goes here
 Scanner sc=new Scanner(System.in);
 int t=sc.nextInt();
 while(t-->0){
     int n=sc.nextInt();
     int m=3*n;
     long []a=new long[m];
     for(int i=0;i<m;i++){
         a[i]=sc.nextLong();
     }
     Arrays.sort(a);
     for(int i=0;i<m/2;i++){
         long te=a[i];
         a[i]=a[m-i-1];
         a[m-i-1]=te;
     }
     long pre[]=new long[m+1];
     for(int i=0;i<m;i++){
         pre[i+1]=pre[i]+a[i];
     }
     long ans=0;
     
     for(int i=0;i<=n;i++){
         int lo=0,hi=n-i;
         while(lo<hi){
             int mid=(lo+hi+1)/2;
             int a1=i+2*(mid-1);
             int a2=3*n-2*i-(mid-1);
             long dist=a[a1]+a[a1+1]-3*a[a2-1];
             if(dist>=0){
                 lo=mid;
             }else{
                 hi=mid-1;
             }
         }
         int mid=lo;
         long cur=2*pre[i]+pre[i+2*mid]+3*pre[3*n-2*i-mid];
         ans=Math.max(ans,cur);
     }
     System.out.println(ans);
 }
	}
}
